<?php require __DIR__.'/../bootstrap.php';admin_only();verify_csrf();$id=(int)($_GET['id']??0);if($_SERVER['REQUEST_METHOD']==='POST'){$pdo->prepare('UPDATE orders SET status=? WHERE id=?')->execute([$_POST['status'],$id]);flash('ok','وضعیت سفارش تغییر کرد.');redirect('admin/order.php?id='.$id);}$s=$pdo->prepare('SELECT o.*,u.name user_name,u.email FROM orders o JOIN users u ON u.id=o.user_id WHERE o.id=?');$s->execute([$id]);$o=$s->fetch();if(!$o)die('سفارش یافت نشد');$si=$pdo->prepare('SELECT * FROM order_items WHERE order_id=?');$si->execute([$id]);$items=$si->fetchAll();$title='سفارش #'.$id;require __DIR__.'/../partials/header.php';?><h1>مدیریت سفارش #<?=$id?></h1><div class="two-col"><div class="panel table-wrap"><table class="table"><tr><th>محصول</th><th>قیمت</th><th>تعداد</th></tr><?php foreach($items as $i): ?><tr><td><?=e($i['product_name'])?></td><td><?=money($i['price'])?></td><td><?=$i['qty']?></td></tr><?php endforeach;?></table></div><div class="panel"><p>کاربر: <?=e($o['user_name'])?> — <?=e($o['email'])?></p><p>آدرس: <?=nl2br(e($o['address']))?></p><p>مبلغ: <b><?=money($o['total'])?></b></p><form method="post"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><div class="field"><label>وضعیت</label><select name="status"><?php foreach(['pending','paid','processing','shipped','completed','cancelled'] as $st): ?><option value="<?=$st?>" <?=$o['status']===$st?'selected':''?>><?=$st?></option><?php endforeach;?></select></div><button class="btn">ثبت وضعیت</button></form></div></div><?php require __DIR__.'/../partials/footer.php'; ?>
